        .init(id:"cottagefruittoast",en:"Cottage cheese toast & berries",zh:"茅屋奶酪吐司配草莓",breakfast:true,minutes:10,starch:"Bread",protein:"Dairy",vegetable:false,ingredients:[.init("bread",10),.init("cottage",750),.init("strawberry",500)],steps:["0–6分钟：面包分批烤热，草莓洗净去蒂切小块。","6–10分钟：吐司抹茅屋奶酪，配草莓分装；余下奶酪及时冷藏。"],favorite:false),
        .init(id:"breakfastburrito",en:"Egg, bean & spinach burritos",zh:"鸡蛋黑豆菠菜早餐卷",breakfast:true,minutes:25,starch:"Bread",protein:"Egg",vegetable:false,ingredients:[.init("tortilla",5),.init("egg",10),.init("blackbean",400),.init("spinach",300),.init("oil",25)],steps:["0–6分钟：黑豆沥水冲洗，菠菜洗切，鸡蛋打散。","6–20分钟：油锅炒菠菜、黑豆至热透，盛出；炒鸡蛋至完全凝固。另一锅温热饼皮。","20–25分钟：豆菜和炒蛋装入饼皮卷紧，切成方便孩子拿取的小段。"],favorite:false),
        .init(id:"breakfastquesadilla",en:"Egg & tomato cheese quesadillas",zh:"鸡蛋番茄芝士早餐夹饼",breakfast:true,minutes:25,starch:"Bread",protein:"Egg",vegetable:false,ingredients:[.init("tortilla",5),.init("egg",8),.init("freshtomato",400),.init("cheddar",150),.init("oil",20)],steps:["0–5分钟：番茄洗净切小丁，鸡蛋打散。","5–13分钟：油锅炒番茄至稍收汁，倒入鸡蛋炒至完全凝固。","13–25分钟：饼半边放蛋、奶酪后对折；两个平底锅并行分批煎至奶酪融化，切块。"],favorite:false),
        .init(id:"corneggporridge",en:"Corn & egg quick rice porridge",zh:"玉米鸡蛋快手粥",breakfast:true,minutes:25,starch:"Rice",protein:"Egg",vegetable:false,ingredients:[.init("rice",250),.init("egg",8),.init("corn",400),.init("milk",500),.init("salt",2)],steps:["0–5分钟：速煮米加约2升水开始煮，鸡蛋打散。此配方用速煮米，不是普通生米慢熬粥。","5–20分钟：加玉米煮至米粒软，适量补水；加入牛奶再次小火煮热。","20–25分钟：缓缓倒蛋液搅成蛋花，煮至完全凝固，加盐，稍放凉再分碗。"],favorite:false),
        .init(id:"savorytofuoats",en:"Savory tofu & egg oats",zh:"豆腐菠菜鸡蛋咸燕麦",breakfast:true,minutes:20,starch:"Oats",protein:"Tofu",vegetable:false,ingredients:[.init("oats",250),.init("tofu",500),.init("egg",5),.init("spinach",300),.init("soy",20),.init("oil",15)],steps:["0–5分钟：豆腐切小丁，菠菜洗切，鸡蛋打散。","5–16分钟：燕麦加约1.5升水煮软，加入豆腐、菠菜和油煮至热透，稠时补水。","16–20分钟：倒入蛋液搅匀煮至完全凝固，加生抽调味后分碗。"],favorite:false),
        .init(id:"breakfasttomatonoodles",en:"Breakfast tomato & egg noodles",zh:"早餐番茄鸡蛋小碗面",breakfast:true,minutes:20,starch:"Noodles",protein:"Egg",vegetable:false,ingredients:[.init("noodles",300),.init("egg",8),.init("tomato",500),.init("spinach",250),.init("oil",20),.init("salt",2)],steps:["0–5分钟：烧水，鸡蛋打散，菠菜洗净。","5–15分钟：锅加油炒蛋至完全凝固，倒碎番茄和热水煮开；加入挂面按包装煮熟。","15–20分钟：加菠菜煮软、盐调味，连汤分成早餐小碗。"],favorite:false),
        .init(id:"eggmuffin",en:"Egg & spinach English muffins",zh:"鸡蛋菠菜芝士英式松饼",breakfast:true,minutes:20,starch:"Bread",protein:"Egg",vegetable:false,ingredients:[.init("englishmuffin",5),.init("egg",8),.init("spinach",250),.init("cheddar",125),.init("oil",20)],steps:["0–6分钟：英式松饼横切后分批烤热，菠菜洗切，鸡蛋打散。","6–16分钟：油锅炒软菠菜，加入蛋液炒至完全凝固。","16–20分钟：把菜蛋和奶酪夹入松饼中，趁热盖合。"],favorite:false),
        .init(id:"hunanpork",en:"Hunan chili pork & rice",zh:"湘味辣椒炒肉配青菜饭",breakfast:false,minutes:30,starch:"Rice",protein:"Pork",vegetable:true,ingredients:[.init("pork",750),.init("freshchili",180),.init("pepper",350),.init("bokchoy",500),.init("garlic",20),.init("soy",30),.init("oil",35),.init("rice",375)],steps:["0–7分钟：速煮米开煮；里脊切薄片，青辣椒、甜椒切片，蒜拍碎，小白菜洗切。此为里脊版家常做法。","7–20分钟：少量油炒青辣椒和甜椒至表面起皱后盛出；另加油分批炒肉片至熟，放蒜、生抽和椒片炒匀。同时另锅清炒小白菜。","20–30分钟：确认猪肉中心达到63°C后保持或静置3分钟；配米饭与小白菜。辣椒品种辣度不同，可减少用量并以甜椒补足。"],favorite:false,cuisine:"Hunan · 湘菜",heat:2),
        .init(id:"hunanbeef",en:"Hunan spicy beef & rice",zh:"湘味小炒牛肉配蔬菜饭",breakfast:false,minutes:30,starch:"Rice",protein:"Beef",vegetable:true,ingredients:[.init("beef",750),.init("celery",350),.init("freshchili",120),.init("carrot",300),.init("ginger",20),.init("garlic",20),.init("soy",30),.init("oil",35),.init("rice",375)],steps:["0–7分钟：速煮米开煮；牛肉逆纹切薄片，芹菜去粗筋切段，青辣椒切圈，姜蒜切末；胡萝卜切薄片。","7–22分钟：胡萝卜另锅蒸熟；大锅热油分批炒牛肉，炒至中心63°C后盛出静置3分钟。原锅炒姜蒜、辣椒、芹菜至熟。","22–30分钟：放回牛肉，加生抽快速拌匀，与米饭、蒸胡萝卜一起装盘。喜欢更辣可另添辣椒；不要给不吃辣的人直接盛此锅。"],favorite:false,cuisine:"Hunan · 湘菜",heat:2),
        .init(id:"hunanchilifish",en:"Hunan chopped-chili fish & rice",zh:"湘味剁椒鱼柳配青菜饭",breakfast:false,minutes:30,starch:"Rice",protein:"Fish",vegetable:true,ingredients:[.init("cod",800),.init("choppedchili",60),.init("ginger",20),.init("garlic",20),.init("scallion",30),.init("bokchoy",700),.init("oil",25),.init("rice",375)],steps:["0–7分钟：速煮米开煮，蒸锅烧水；已解冻去刺鱼柳切成厚度约2厘米的块，铺姜蒜和剁椒。这里用鱼柳代替鱼头，便于家庭操作。","7–23分钟：水开后蒸鱼约10–15分钟，厚块需延长，中心达到63°C；另锅用油炒熟小白菜。剁椒已有盐，不额外加盐。","23–30分钟：鱼上撒葱花，配米饭和白菜。若有人不吃辣，用独立蒸盘做姜葱鱼，避免辣汁混入；购买量按实际做的版本调整。"],favorite:false,cuisine:"Hunan · 湘菜",heat:2),
        .init(id:"sichuanmapo",en:"Mapo tofu, greens & rice",zh:"川味麻婆豆腐配青菜饭",breakfast:false,minutes:30,starch:"Rice",protein:"Tofu",vegetable:true,ingredients:[.init("tofu",900),.init("groundpork",300),.init("douban",45),.init("peppercorn",3),.init("garlic",20),.init("scallion",30),.init("cornstarch",15),.init("bokchoy",650),.init("oil",30),.init("rice",375)],steps:["0–7分钟：速煮米开煮；豆腐切块，葱蒜切末，小白菜洗净；淀粉用少量冷水调开。","7–22分钟：锅加油炒散猪肉末至中心71°C，再放蒜和豆瓣酱小火炒香；加约350mL水，放豆腐轻推煮8分钟。同时另锅炒熟白菜。","22–30分钟：分次加淀粉水煮至薄芡，撒花椒粉和葱花；配米饭、白菜。豆瓣酱已有盐。花椒和豆瓣可减量，豆瓣仍有辣味。"],favorite:false,cuisine:"Sichuan · 川菜",heat:2),
        .init(id:"sichuankungpao",en:"Kung pao chicken & rice",zh:"川味宫保鸡丁配蔬菜饭",breakfast:false,minutes:30,starch:"Rice",protein:"Chicken",vegetable:true,ingredients:[.init("chicken",750),.init("cucumber",350),.init("carrot",350),.init("peanut",80),.init("driedchili",8),.init("peppercorn",2),.init("scallion",40),.init("garlic",15),.init("soy",30),.init("vinegar",25),.init("sugar",15),.init("cornstarch",15),.init("oil",35),.init("rice",375)],steps:["0–8分钟：速煮米开煮；鸡肉切小丁，黄瓜、胡萝卜切小丁，葱蒜切碎；生抽、醋、糖、淀粉加80mL水拌匀。","8–22分钟：胡萝卜加少量水焖软备用。大锅热油分批炒鸡丁至中心74°C，盛出；原锅小火炒干辣椒和蒜，避免炒焦，再放回鸡肉和蔬菜。","22–30分钟：倒入搅匀的调味汁炒至浓稠，加花椒粉、葱和熟花生，配米饭。此为加蔬菜家常版；整段干辣椒可挑出，菜汁仍辣。含花生。"],favorite:false,cuisine:"Sichuan · 川菜",heat:1),
        .init(id:"sichuanyuxiang",en:"Yu-xiang pork & rice",zh:"川味鱼香肉丝配米饭",breakfast:false,minutes:30,starch:"Rice",protein:"Pork",vegetable:true,ingredients:[.init("pork",750),.init("carrot",350),.init("pepper",350),.init("mushroom",250),.init("douban",35),.init("ginger",15),.init("garlic",20),.init("soy",20),.init("vinegar",30),.init("sugar",20),.init("cornstarch",15),.init("oil",35),.init("rice",375)],steps:["0–8分钟：速煮米开煮；里脊、胡萝卜、甜椒、蘑菇切细丝。生抽、醋、糖、淀粉加100mL水拌成调味汁。鱼香是调味名称，此配方不含鱼。","8–22分钟：大锅热油分批炒肉丝至中心63°C，盛出静置3分钟；原锅小火炒姜蒜和豆瓣酱，再放蔬菜丝，加少许水炒至熟软。","22–30分钟：肉丝回锅，调味汁重新搅匀后倒入，炒至芡汁均匀裹住食材，配米饭。此为蘑菇替代木耳的家常版，豆瓣用量可减少。"],favorite:false,cuisine:"Sichuan · 川菜",heat:1)
    ]
}
public func quantityText(_ value: Double, unit: String) -> String {
    let rounded = (unit == "each" || unit == "slice") ? ceil(value) : ceil(value * 10) / 10
    return "\(rounded.formatted(.number.precision(.fractionLength(0...1)))) \(unit)"
}
